void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = texelFetch(iChannel0, ivec2(fragCoord), 0);
}

#define OVERLAY
#define TAU 6.28
#define BEAT 0.52476
float sampleFreqs(int bandFrom, int bandTo) {
    float v = 0.0;
    for (int b = bandFrom; b <= bandTo; b++)
        v += texelFetch(iChannel1, ivec2(b, 0), 0).x;
    return v / float(bandTo - bandFrom);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // settings
    const uint N = 4u;
    const int L = 4;
    const float speed = 0.15;
    const float scale = 0.38;
    const float width = 0.18;
    const float sens = 0.7;
    const float ghost = 0.8;
    const float levels = 12.;
    const float carousel = BEAT * 8.;

    vec2 uv = (fragCoord - iResolution.xy / 2.) / iResolution.y;
    uv *= 1.01;
    float cellSide = 1. / float(L);
    float oddOffset = float(L % 2) * cellSide / 2.;

    vec3 rgb;
    float prox;
    float sound = sampleFreqs(0, 4) * sens;
    float dPhase = TAU / float(N);
    int l = int(floor(mod(iTime / carousel, float(L * L))));
    ivec2 lissCarousel = ivec2(l / L, l % L) + 1;
    vec2 muv = (iMouse.xy - iResolution.xy / 2.) / iResolution.y;
    muv += oddOffset;
    ivec2 lissMouse = ivec2(floor(muv * float(L)) + float(L) / 2. + 1.);
    ivec2 liss = (iMouse.z <= 0.) ? lissCarousel : lissMouse;
    liss = clamp(liss, 1, L);
    for (uint i = 0u; i < N; i++) {
        float phase = float(i) * dPhase;
        vec2 p = lissajous(iTime * speed + phase, liss) * scale;
        float d = length(uv - p);
        rgb += hsv2rgb(vec3(phase / TAU, 10., 0.05 / max(0.1, d)));
        prox += atan(atan(atan((d)))) / float(N);
    }
    rgb /= float(N);
    vec3 old = texelFetch(iChannel0, ivec2(fragCoord), 0).rgb;
    sound = mix(0.9, 1.1, sound) - 1.;
    sound = sound * sound + 1.;
    vec3 new = rgb * rgb * sound * step(1. - width, compress(sin(-iTime * 0. + prox * 69. * levels * scale * sound)));
    fragColor.rgb = mix(new, old, ghost);

    #ifdef OVERLAY
    float aspect = iResolution.x / iResolution.y;
    float hairline = aspect / iResolution.x;
    vec2 uvOdd = uv + oddOffset;
    bool x = mod(uvOdd.x, cellSide) < hairline &&
        abs(uv.x) <= cellSide * float(L + 1) / 2. &&
        (length(uvOdd - round(uvOdd * float(L)) / float(L)) < 0.006);
    bool y = mod(uvOdd.y, cellSide) < hairline &&
        abs(uv.x) <= cellSide * float(L + 1) / 2. &&
        (length(uvOdd - round(uvOdd * float(L)) / float(L)) < 0.006);
    vec2 lissUv = (vec2(liss) - 0.5 - float(L) / 2.) * cellSide;
    bool cell = length(uv - lissUv) < 0.02;
    bool time = (uv.y < -0.495) && (fragCoord.x / iResolution.x) < mod(iTime / carousel, 1.) && (iMouse.z <= 0.);
    bool curve = false;
    float d = 1.;
    float T = TAU * float(lcm(liss.x, liss.y)) / float(liss.x * liss.y);
    float dt = iResolution.x / 200000.;
    for (float t = -T * 0.5; t < T * 0.5; t += dt) {
        float phase = mod(iTime * 0.1, dt);
        vec2 p = lissajous(t + phase, liss) * scale;
        d = min(d, length(uv - p));
        curve = d < 0.003;
        if (curve) break;
    }

    if (x || y || cell || time || curve)
        fragColor.r += .07 / ghost;
    #endif
}

vec2 lissajous(float t, ivec2 freqs){
    float x = sin(float(freqs.x) * t);
    float y = cos(float(freqs.y) * t);
    return vec2(x, y);
}

float compress(float x){
    return (x + 1.) / 2.;
}

//HSV (hue, saturation, value) to RGB.
//Sources: https://gist.github.com/yiwenl/745bfea7f04c456e0101, https://gist.github.com/sugi-cho/6a01cae436acddd72bdf
#define saturate(v) clamp(v,0.,1.)
vec3 hsv2rgb(vec3 c){
	vec4 K=vec4(1.,2./3.,1./3.,3.);
	return c.z*mix(K.xxx,saturate(abs(fract(c.x+K.xyz)*6.-K.w)-K.x),c.y);
}

int lcm(int a, int b){
    int i,j=1;
    if (a*b == 0) return 0;
    while (true){
        if (a*i > b*j) j++;
        else if (a*i < b*j) i++;
        else return a*i;
    }
}
